rows = input if isinstance(input, list) else []
billable = []
rejected = []
for row in rows:
    if isinstance(row, dict) and isinstance(row.get("email"), str) and row.get("email").strip() and isinstance(row.get("amount_cents"), int) and not isinstance(row.get("amount_cents"), bool) and row.get("amount_cents") > 0:
        billable.append({"email": row.get("email").strip().lower(), "amount_cents": row.get("amount_cents")})
    else:
        rejected.append({"row": row, "reason": "invalid_input"})
output = {"billable": billable, "rejected": rejected}

dedup = input.get("dedup_output") or {}
clean = dedup.get("clean") or []
output = {"billable_count": len(clean), "total_cents": sum(x.get("amount_cents") or 0 for x in clean), "proceed": bool(clean)}

plan = input.get("plan_summary_output") or {}
charge = input.get("charge_output") or {}
items = charge.get("items") if isinstance(charge.get("items"), list) else []
output = {"intended": plan.get("billable_count") or 0, "landed": len(items), "difference": (plan.get("billable_count") or 0) - len(items)}

def is_valid_amount(v):
    return isinstance(v, int) and not isinstance(v, bool) and v > 0

rows = input if isinstance(input, list) else []
billable = []
rejected = []
for row in rows:
    if not isinstance(row, dict):
        rejected.append({"row": row, "reason": "not_an_object"})
        continue
    email = row.get("email")
    amount = row.get("amount_cents")
    if not isinstance(email, str) or not email.strip():
        rejected.append({"row": row, "reason": "missing_email"})
        continue
    if not is_valid_amount(amount):
        rejected.append({"row": row, "reason": "invalid_amount"})
        continue
    billable.append({
        "email": email.strip().lower(),
        "customer_id": str(row.get("customer_id") or "").strip(),
        "amount_cents": amount,
    })
output = {"billable": billable, "rejected": rejected}

vo = input.get("validate_output") or {}
billable = vo.get("billable") or []
already = set(
    x.strip().lower()
    for x in (input.get("already_billed") or [])
    if isinstance(x, str) and x.strip()
)
period = str(input.get("period") or "").strip()
description = "Retainer billing for " + period if period else "Retainer billing"
history = input.get("invoice_history") or {}
history_rows = history.get("invoices") if isinstance(history, dict) else []
history_rows = history_rows if isinstance(history_rows, list) else []
history_truncated = bool(history.get("truncated")) if isinstance(history, dict) else False
history_keys = set()
for invoice in history_rows:
    if not isinstance(invoice, dict):
        continue
    email = invoice.get("customer_email")
    amount = invoice.get("amount_due_cents")
    created = invoice.get("created_at")
    if not isinstance(email, str) or not email.strip():
        continue
    if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
        continue
    if invoice.get("description") != description:
        continue
    if not isinstance(created, str) or created[:7] != period:
        continue
    if invoice.get("status") not in ("open", "paid", "uncollectible"):
        continue
    history_keys.add((email.strip().lower(), amount))
seen = set()
clean = []
skipped = []
for row in billable:
    email = row.get("email")
    amount = row.get("amount_cents")
    key = email.strip().lower()
    if key in seen:
        skipped.append({"email": email, "amount_cents": amount, "reason": "duplicate_in_export"})
        continue
    seen.add(key)
    if key in already:
        skipped.append({"email": email, "amount_cents": amount, "reason": "already_billed_this_period"})
        continue
    if history_truncated:
        skipped.append({"email": email, "amount_cents": amount, "reason": "invoice_history_truncated_fail_closed"})
        continue
    if (key, amount) in history_keys:
        skipped.append({"email": email, "amount_cents": amount, "reason": "stripe_history_same_period"})
        continue
    clean.append({
        "email": email,
        "customer_id": row.get("customer_id") or "",
        "amount_cents": amount,
        "description": description,
        "period": period,
    })
output = {
    "clean": clean,
    "skipped": skipped,
    "history_invoices_considered": len(history_keys),
    "history_truncated": history_truncated,
    "stripe_history_skipped_count": len([x for x in skipped if x.get("reason") == "stripe_history_same_period"]),
}

plan = input.get("plan_summary_output") or {}
skipped = plan.get("skipped") or []
rejected = plan.get("rejected") or []
candidates = plan.get("candidates") or []
period = str(plan.get("billing_period") or "")
config = input.get("anomaly_config") or {}
anomalies = []
for row in skipped:
    reason = row.get("reason")
    if reason in ("duplicate_in_export", "stripe_history_same_period"):
        anomalies.append({"kind": "duplicate_candidate", "severity": "warning", "reason": reason})
for row in rejected:
    if row.get("reason") == "invalid_amount":
        anomalies.append({"kind": "invalid_or_suspicious_amount", "severity": "blocking", "reason": "validation rejected an amount"})
if not period or len(period) != 7 or period[4] != "-":
    anomalies.append({"kind": "unexpected_billing_period", "severity": "blocking", "reason": "billing period must be YYYY-MM"})
large_batch = int(config.get("large_batch_total_cents") or 50000)
if (plan.get("total_planned_cents") or 0) >= large_batch:
    anomalies.append({"kind": "large_batch_total", "severity": "warning", "reason": "planned total meets configured review threshold"})
known = set(x.strip().lower() for x in (input.get("known_customer_emails") or []) if isinstance(x, str))
prior = input.get("prior_amount_by_email") or {}
prior_ids = input.get("prior_customer_ids") or {}
multiple = float(config.get("large_amount_multiple") or 2)
high_value = int(config.get("high_value_cents") or 25000)
for row in candidates:
    email = row.get("email")
    amount = row.get("amount_cents") or 0
    customer_id = row.get("customer_id") or ""
    if email not in known:
        anomalies.append({"kind": "new_customer", "severity": "warning", "email": email})
    if amount >= high_value:
        anomalies.append({"kind": "high_value_customer", "severity": "warning", "email": email})
    previous = prior.get(email)
    if isinstance(previous, int) and previous > 0 and amount > previous * multiple:
        anomalies.append({"kind": "large_change", "severity": "warning", "email": email})
    previous_customer_id = prior_ids.get(email)
    if previous_customer_id and customer_id and previous_customer_id != customer_id:
        anomalies.append({"kind": "changed_customer_mapping", "severity": "blocking", "email": email})
output = {
    "billing_run_id": plan.get("billing_run_id") or "",
    "plan_hash": plan.get("plan_hash") or "",
    "billing_period": period,
    "candidate_count": len(candidates),
    "total_planned_cents": plan.get("total_planned_cents") or 0,
    "skipped_count": len(skipped),
    "rejected_count": len(rejected),
    "anomalies": anomalies,
    "blocking_anomaly_count": len([x for x in anomalies if x.get("severity") == "blocking"]),
    "review_required": bool(anomalies),
    "summary": "Review " + str(len(candidates)) + " clients for " + str(plan.get("total_planned_cents") or 0) + " cents; plan " + str(plan.get("plan_hash") or ""),
}

plan = input.get("plan_summary_output") or {}
review = input.get("review_output") or {}
tiers = input.get("approval_tiers") or {}
small_max = int(tiers.get("small_batch_max_cents") or 10000)
small_quorum = int(tiers.get("small_batch_quorum") or 1)
large_quorum = int(tiers.get("large_batch_quorum") or 2)
total = int(plan.get("total_planned_cents") or 0)
required_quorum = small_quorum if total <= small_max else large_quorum
if required_quorum < 1:
    required_quorum = 1
output = {
    "billing_run_id": plan.get("billing_run_id") or "",
    "plan_hash": plan.get("plan_hash") or "",
    "required_quorum": required_quorum,
    "tier": "small" if total <= small_max else "large",
    "risk_anomaly_count": len(review.get("anomalies") or []),
    "station_authority": True,
    "approval_status": "not_asserted_by_workflow",
    "approval_evidence": "must come from Station; workflow does not fabricate approver or quorum evidence",
}

clean = input.get("clean") or []
records = []
for index, row in enumerate(clean):
    records.append({
        "record_ref": "batch-" + str(index + 1),
        "amount_cents": int(row.get("amount_cents") or 0),
        "invoice_count": 1,
    })
output = {
    "billing_period": str(input.get("billing_period") or ""),
    "portfolio": records,
    "portfolio_baseline_cents": input.get("portfolio_baseline_cents") or 0,
}

reconcile = input.get("reconcile_output") or {}
outcomes = reconcile.get("outcomes") or []
retry = []
for row in outcomes:
    if row.get("state") in ("failed", "unknown"):
        retry.append({
            "email": row.get("email"),
            "amount_cents": row.get("amount_cents"),
            "billing_run_id": row.get("billing_run_id"),
            "plan_hash": row.get("plan_hash"),
            "retry_policy": "provider_truth_and_idempotency_required",
        })
output = {
    "billing_run_id": reconcile.get("billing_run_id") or "",
    "plan_hash": reconcile.get("plan_hash") or "",
    "retry_candidates": retry,
    "safe_to_retry": False if retry else True,
    "watermark_action": "hold" if retry else "advance_only_after_Station_completion",
    "provider_truth_required": bool(retry),
}

reconcile = input.get("reconcile_output") or {}
recovery = input.get("recovery_output") or {}
output = {
    "billing_run_id": reconcile.get("billing_run_id") or recovery.get("billing_run_id") or "",
    "plan_hash": reconcile.get("plan_hash") or recovery.get("plan_hash") or "",
    "settlement_status": reconcile.get("settlement_status") or "unresolved",
    "unresolved_amount_cents": reconcile.get("unresolved_amount_cents") or 0,
    "recovery_required": bool(recovery.get("retry_candidates")),
    "watermark_action": recovery.get("watermark_action") or "hold",
    "station_watermark_owner": True,
}
